#!/usr/bin/env bash
# libmachinahash — MachinaHash as a shared library for callers that are not Go.
#
# It exists so a pool can verify shares with **our** implementation instead of a second one written
# in C# (project rule 1). The pool must never rebuild consensus bytes itself.
#
#   scripts/build-libmachinahash.sh            # for this machine, into bin/
#   scripts/build-libmachinahash.sh --docker   # in the pinned builder, reproducibly
#
# The result is libmachinahash.so + libmachinahash.h. The header is generated by cgo and is what the
# C# side's P/Invoke signatures have to agree with — when the ABI changes, mh_abi() goes up and the
# caller refuses the mismatch rather than hashing nonsense.
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.." && pwd)
OUT=${OUT:-$ROOT/bin}
BUILDER=golang@sha256:972b4110ba0f47539a975c31e52c64765e1ff19f2d74469ae4a595c6676e80a5

mkdir -p "$OUT"
if [ "${1:-}" = "--docker" ]; then
	# The same pinned image as the release, so the pool's library can be rebuilt from a commit.
	docker run --rm -v "$ROOT":/src:ro -v "$OUT":/out -v powm-release-mod:/go/pkg/mod -w /src \
		"$BUILDER" sh -euc '
			apt-get update -qq && apt-get install -y -qq --no-install-recommends build-essential >/dev/null
			CGO_ENABLED=1 go build -trimpath -buildvcs=false -buildmode=c-shared \
				-ldflags="-s -w -buildid=" -o /out/libmachinahash.so ./cmd/libmachinahash
		'
else
	cd "$ROOT"
	CGO_ENABLED=1 go build -trimpath -buildmode=c-shared -o "$OUT/libmachinahash.so" ./cmd/libmachinahash
fi
echo "→ $OUT/libmachinahash.so"
echo "→ $OUT/libmachinahash.h"
